node --input-type=module -e "
import ts from 'typescript';
import {mkdtempSync, writeFileSync, mkdirSync, rmSync, readFileSync} from 'node:fs';
import {join} from 'node:path';

const dir = mkdtempSync('/var/tmp/loop-bench/runs/4f3c16539170/home-1/.gemini/tmp/workspace/ts-ajv-check-');
try {
  mkdirSync(join(dir, 'node_modules/ajv'), {recursive: true});
  mkdirSync(join(dir, 'src/orchestration/tools'), {recursive: true});
  mkdirSync(join(dir, 'src/types'), {recursive: true});
  mkdirSync(join(dir, 'src/shared'), {recursive: true});
  writeFileSync(join(dir, 'package.json'), JSON.stringify({type: 'module'}));
  writeFileSync(join(dir, 'node_modules/ajv/package.json'), JSON.stringify({name: 'ajv', main: 'index.js', types: 'index.d.ts'}));
  writeFileSync(join(dir, 'node_modules/ajv/index.d.ts'), [
    'export interface ErrorObject<K extends string = string, P = Record<string, any>> { keyword: K; instancePath: string; schemaPath: string; params: P; message?: string; }',
    'export interface ValidateFunction<T = unknown> { (data: unknown): data is T; errors?: ErrorObject[] | null; }',
    'export default class Ajv { constructor(opts?: any); compile(schema: Record<string, unknown>): ValidateFunction; }',
    'export type { Ajv };',
  ].join('\n'));
  writeFileSync(join(dir, 'src/types/ai.ts'), 'export interface ToolDefinition { name: string; description: string; inputSchema: Record<string, unknown>; promptInstructions?: string; examplePrompts?: string[]; }\n');
  writeFileSync(join(dir, 'src/types/messages.ts'), 'export interface OutgoingMessage { type: string; }\n');
  writeFileSync(join(dir, 'src/shared/logger.ts'), 'export const log = { warn: (..._a: unknown[]) => {}, info: (..._a: unknown[]) => {} };\n');
  writeFileSync(join(dir, 'src/orchestration/tools/registry.ts'), readFileSync('src/orchestration/tools/registry.ts', 'utf8'));
  const opts = {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
    strict: true,
    esModuleInterop: true,
    skipLibCheck: true,
  };
  const prog = ts.createProgram([join(dir, 'src/orchestration/tools/registry.ts')], opts);
  const diags = ts.getPreEmitDiagnostics(prog);
  console.log('diags:', diags.map(d => ts.flattenDiagnosticMessageText(d.messageText, ' ')));
} finally {
  rmSync(dir, {recursive: true, force: true});
}
"
